<template><view class="login-page"><view class="brand"><image src="/static/aircon/ai-robot.png" /><text>格宏助手</text><text>空调产品中心 · 智能报价助手</text></view><view class="login-card"><text class="title">欢迎登录</text><up-form labelPosition="top"><up-form-item label="手机号/账号"><up-input v-model="form.username" placeholder="请输入手机号或账号" border="surround" /></up-form-item><up-form-item label="密码"><up-input v-model="form.password" type="password" placeholder="请输入密码" border="surround" /></up-form-item></up-form><up-button type="primary" shape="circle" :loading="loading" @click="handleLogin">登录</up-button><view class="demo" @click="fillDemo">使用演示账号快速登录</view></view></view></template>
<script setup>
import { reactive, ref } from 'vue'; import { login } from '@/api/auth'; import { useUserStore } from '@/store/user'; import { replacePage } from '@/utils/pages';
const form=reactive({username:'',password:''});const loading=ref(false);const userStore=useUserStore();const fillDemo=()=>{form.username='demo';form.password='123456'};const handleLogin=async()=>{if(!form.username){uni.showToast({title:'请输入账号',icon:'none'});return}loading.value=true;try{const result=await login(form);userStore.setToken(result.token);userStore.setUserInfo(result.user);replacePage('/pages/index/index')}finally{loading.value=false}};
</script>
<style lang="scss" scoped>.login-page{min-height:100vh;padding:120rpx 40rpx 40rpx;background:linear-gradient(180deg,#edf4ff,#f7f9fc)}.brand{text-align:center}.brand image{width:150rpx;height:150rpx;border-radius:50%}.brand text{display:block}.brand text:nth-child(2){margin-top:18rpx;color:#17233d;font-size:42rpx;font-weight:700}.brand text:nth-child(3){margin-top:10rpx;color:#8b95a7;font-size:23rpx}.login-card{padding:32rpx;margin-top:70rpx;background:#fff;border-radius:24rpx;box-shadow:0 16rpx 40rpx rgba(31,64,120,.08)}.title{display:block;margin-bottom:28rpx;color:#17233d;font-size:36rpx;font-weight:700}.demo{margin-top:24rpx;text-align:center;color:#2468e8;font-size:23rpx}</style>
